/**
 * Client for the Python AI service (apps/ai), generated from its OpenAPI document:
 *
 *   apps/ai/app (Pydantic models) ──(bun run gen)──▶ apps/ai/openapi.json
 *                                 ──(bun run gen)──▶ src/generated (types + zod)
 *
 * Every response is validated against the generated zod schemas, so a contract change
 * on the Python side fails here instead of passing bad data on. Never edit
 * src/generated by hand; CI fails if it's out of date.
 *
 * Each call carries a token signed for that call (60 seconds, AI_SERVICE_SECRET) naming
 * the user and organization it's for: the service trusts nothing else.
 */
import { SignJWT } from "jose";
import * as z from "zod";
import { createClient } from "./generated/client";
import {
  checkDirectorScene,
  clipDirectorAttempt,
  createDirectorCut,
  createDirectorTake,
  getDirectorCut,
  getDirectorLibrary,
  getDirectorPlan,
  indexDirectorPlan,
  listDirectorCuts,
  listDirectorMedia,
  listDirectorTakes,
  locateDirectorTarget,
  speakDirectorLine,
  writeDirectorPublishCopy,
} from "./generated/sdk.gen";
import type {
  ClipRequest,
  DirectorCutCreate,
  DirectorTakeCreate,
  ErrorCode,
  ErrorIssue,
  LocateRequest,
  PublishCopyRequest,
  SceneCheckRequest,
  SpeechRequest,
} from "./generated/types.gen";
import { zErrorResponse } from "./generated/zod.gen";

export interface AiCaller {
  userId: string;
  orgId: string;
  requestId?: string | undefined;
}

/**
 * A failure the service reported, with its stable error code, or UPSTREAM_UNAVAILABLE
 * when it couldn't be reached or answered with something other than an error body.
 */
export class AiServiceError extends Error {
  constructor(
    readonly status: number,
    readonly code: ErrorCode,
    readonly params: Record<string, string | number> = {},
    readonly issues: ErrorIssue[] = [],
  ) {
    super(`AI service answered ${status} ${code}`);
  }
}

/** The error a failed response carries, parsed against the service's error model. */
function toServiceError(status: number, body: unknown): AiServiceError {
  const parsed = zErrorResponse.safeParse(body);
  if (!parsed.success) {
    return new AiServiceError(status, "UPSTREAM_UNAVAILABLE");
  }
  const { code, data } = parsed.data;
  return new AiServiceError(status, code, data.params, data.issues ?? []);
}

const TOKEN_LIFETIME_SECONDS = 60;

/** Where a clip was cut, as its response's headers say: whole milliseconds. */
const milliseconds = z.string().regex(/^\d+$/).transform(Number);
const clipWindow = z.object({ startMs: milliseconds, endMs: milliseconds });

/** A call's headers: its own token, naming the user and organization, and the request id. */
async function callHeaders(key: Uint8Array, caller: AiCaller) {
  const token = await new SignJWT({ org: caller.orgId })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuer("api")
    .setAudience("ai")
    .setSubject(caller.userId)
    .setIssuedAt()
    .setExpirationTime(`${TOKEN_LIFETIME_SECONDS}s`)
    .sign(key);
  return {
    authorization: `Bearer ${token}`,
    ...(caller.requestId && { "x-request-id": caller.requestId }),
  };
}

/** The result of a call that succeeded; the service's error (or an outage) otherwise. */
async function settle<R extends { error?: unknown; response?: Response }>(
  call: Promise<R>,
): Promise<R> {
  // The generated client never rejects: an unreachable service comes back as a result
  // without a response.
  const result = await call;
  if (!result.response?.ok) {
    throw toServiceError(result.response?.status ?? 503, result.error);
  }
  return result;
}

async function unwrap<T>(call: Promise<{ data?: T; error?: unknown; response?: Response }>) {
  const { data } = await settle(call);
  // The generated client validated the body; one that broke the contract lands here.
  if (data === undefined) {
    throw new AiServiceError(502, "UPSTREAM_UNAVAILABLE");
  }
  return data;
}

/** Director's calls (apps/ai/app/director.py), each on a client made for that call. */
function directorCalls(forCall: (caller: AiCaller) => Promise<ReturnType<typeof createClient>>) {
  return {
    async index(caller: AiCaller, videoId: string) {
      return unwrap(indexDirectorPlan({ client: await forCall(caller), body: { videoId } }));
    },
    async library(caller: AiCaller) {
      return unwrap(getDirectorLibrary({ client: await forCall(caller) }));
    },
    async getPlan(caller: AiCaller, videoId: string) {
      return unwrap(
        getDirectorPlan({ client: await forCall(caller), path: { video_id: videoId } }),
      );
    },
    async checkScene(caller: AiCaller, body: SceneCheckRequest) {
      return unwrap(checkDirectorScene({ client: await forCall(caller), body }));
    },
    async locate(caller: AiCaller, body: LocateRequest) {
      return unwrap(locateDirectorTarget({ client: await forCall(caller), body }));
    },
    async createTake(caller: AiCaller, body: DirectorTakeCreate) {
      return unwrap(createDirectorTake({ client: await forCall(caller), body }));
    },
    async listTakes(caller: AiCaller, videoId: string) {
      return unwrap(
        listDirectorTakes({ client: await forCall(caller), path: { video_id: videoId } }),
      );
    },
    async createCut(caller: AiCaller, body: DirectorCutCreate) {
      return unwrap(createDirectorCut({ client: await forCall(caller), body }));
    },
    async listCuts(caller: AiCaller, videoId: string) {
      return unwrap(
        listDirectorCuts({ client: await forCall(caller), path: { video_id: videoId } }),
      );
    },
    async listMedia(caller: AiCaller) {
      return unwrap(listDirectorMedia({ client: await forCall(caller) }));
    },
    /** A line in Director's voice: the bytes of the WAV file the service spoke. */
    async speak(caller: AiCaller, body: SpeechRequest): Promise<Uint8Array> {
      // Read as bytes rather than JSON (this client's default); there's no schema to check
      // them against, so the content type is the contract.
      const { data, response } = await settle(
        speakDirectorLine({ client: await forCall(caller), body, parseAs: "blob" }),
      );
      if (!data || response?.headers.get("content-type") !== "audio/wav") {
        throw new AiServiceError(502, "UPSTREAM_UNAVAILABLE");
      }
      return new Uint8Array(await data.arrayBuffer());
    },
    /**
     * A recorded attempt cut into a take: the MP4's bytes, and where in its part it was
     * cut (the headers say; the bytes have no schema to check, so the type and those
     * headers are the contract).
     */
    async clip(caller: AiCaller, body: ClipRequest) {
      const { data, response } = await settle(
        clipDirectorAttempt({ client: await forCall(caller), body, parseAs: "blob" }),
      );
      const cut = clipWindow.safeParse({
        startMs: response?.headers.get("x-clip-start-ms"),
        endMs: response?.headers.get("x-clip-end-ms"),
      });
      if (!data || response?.headers.get("content-type") !== "video/mp4" || !cut.success) {
        throw new AiServiceError(502, "UPSTREAM_UNAVAILABLE");
      }
      return { video: new Uint8Array(await data.arrayBuffer()), ...cut.data };
    },
    async getCut(caller: AiCaller, cutId: string) {
      return unwrap(getDirectorCut({ client: await forCall(caller), path: { cut_id: cutId } }));
    },
    async writePublishCopy(caller: AiCaller, body: PublishCopyRequest) {
      return unwrap(writeDirectorPublishCopy({ client: await forCall(caller), body }));
    },
  };
}

export function createAiClient(options: { baseUrl: string; secret: string; timeoutMs?: number }) {
  const key = new TextEncoder().encode(options.secret);
  const timeoutMs = options.timeoutMs ?? 30_000;

  /** A client for one call: its token, and a timeout so a hung service can't hang us. */
  async function forCall(caller: AiCaller) {
    return createClient({
      baseUrl: options.baseUrl,
      headers: await callHeaders(key, caller),
      // Always JSON, so the validator sees every body: left to the content type, a body
      // without one would come back as a raw stream, unchecked.
      parseAs: "json",
      fetch: (input: RequestInfo | URL, init?: RequestInit) =>
        fetch(input, { ...init, signal: AbortSignal.timeout(timeoutMs) }),
    });
  }

  /** Director's calls, as `ai.director.index(...)`. */
  return { director: directorCalls(forCall) };
}
